61	    ///
62	    /// This function will try to acquire the master lock for the underlying drm device
63	    /// and release the lock on drop again.
64	    /// For that reason you should never create multiple `DrmDeviceFd` out of the same
65	    /// `DeviceFd`, but instead clone the `DrmDeviceFd`.
66	    ///
67	    /// Failing to do so might fail to acquire set lock and release it early,
68	    /// which can cause some drm ioctls to fail later.
69	    pub fn new(fd: DeviceFd) -> DrmDeviceFd {
70	        let mut dev = InternalDrmDeviceFd {
71	            fd,
72	            privileged: false,
73	        };
74	
75	        // Render nodes have no master; the kernel refuses SET_MASTER on them.
76	        let is_render_node = DrmNode::from_file(&dev.fd).is_ok_and(|node| node.ty() == NodeType::Render);
77	
78	        // We want to modeset, so we better be the master, if we run via a tty session.
79	        // This is only needed on older kernels. Newer kernels grant this permission,
80	        // if no other process is already the *master*. So we skip over this error.
81	        if !is_render_node {
82	            if dev.acquire_master_lock().is_err() {
83	                warn!("Unable to become drm master, assuming unprivileged mode");
84	            } else {
85	                dev.privileged = true;
86	            }
87	        }
88	
89	        DrmDeviceFd(Arc::new(dev))
