//! Manual native initialization probe. This is not a compositor or modeset demo.
use flux_native::system::{Driver, Failure, NativeEvent};
use serde_json::json;
use smithay::reexports::calloop::{
    Dispatcher, EventLoop,
    signals::{Signal, Signals},
    timer::{TimeoutAction, Timer},
};
use std::time::Duration;
#[derive(Default)]
struct State {
    driver: Option<Driver<Self>>,
    input_events: u64,
    gpu_preparations: u64,
    gpu_removals: u64,
    session_transitions: u64,
    vblanks: u64,
    failures: Vec<Failure>,
    failure_events: u64,
}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args_os().skip(1).collect();
    match args.as_slice() {
        [] => {
            help();
            return Ok(());
        }
        [arg] if arg == "--help" || arg == "-h" => {
            help();
            return Ok(());
        }
        [arg] if arg == "--check" => {
            println!(
                "{}",
                serde_json::to_string_pretty(
                    &json!({"scope":"read-only udev inventory; no native desktop qualification","session_opened":false,"gpu_contexts_created":0,"native_compositor":false,"devices":flux_native::system::device_ids("seat0")?})
                )?
            );
            return Ok(());
        }
        [arg] if arg == "--session" => (),
        _ => return Err("expected --check, --session or --help".into()),
    }
    // Own signal masking before GPU libraries can start helper threads. This
    // independent dispatcher outlives all native resources, including errors.
    let signals = Signals::new(&[Signal::SIGINT, Signal::SIGTERM])?;
    let mut event_loop = EventLoop::<State>::try_new()?;
    let stop = event_loop.get_signal();
    let signal_owner = Dispatcher::new(signals, move |_, _, _: &mut State| stop.stop());
    event_loop
        .handle()
        .register_dispatcher(signal_owner.clone())
        .map_err(|_| "failed to register signals")?;
    let mut state = State::default();
    let driver = Driver::new(
        &event_loop.handle(),
        &mut state,
        |event, state| match event {
            NativeEvent::Input(_) => state.input_events = state.input_events.saturating_add(1),
            NativeEvent::GpuReady(_) => {
                state.gpu_preparations = state.gpu_preparations.saturating_add(1)
            }
            NativeEvent::GpuRemoved(_) => state.gpu_removals = state.gpu_removals.saturating_add(1),
            NativeEvent::SessionActive(_) => {
                state.session_transitions = state.session_transitions.saturating_add(1)
            }
            NativeEvent::VBlank { .. } => state.vblanks = state.vblanks.saturating_add(1),
            NativeEvent::Failure { error, .. } => {
                state.failure_events = state.failure_events.saturating_add(1);
                if state.failures.len() < 32 {
                    state.failures.push(error);
                }
            }
        },
    )?;
    state.driver = Some(driver);
    let stop = event_loop.get_signal();
    event_loop
        .handle()
        .insert_source(
            Timer::from_duration(Duration::from_secs(15)),
            move |_, _, _| {
                stop.stop();
                TimeoutAction::Drop
            },
        )
        .map_err(|_| "failed to register exit timer")?;
    event_loop.run(None, &mut state, |_| {})?;
    let mut driver = state.driver.take().ok_or("native driver missing")?;
    let before = driver.snapshot();
    let gpus = driver.gpu_info();
    driver.stop();
    let after = driver.snapshot();
    let close_failures = driver.close_failures();
    drop(driver);
    let initialization_healthy = initialization_healthy(
        before.active,
        before.closed,
        gpus.len(),
        state.failure_events,
        close_failures,
    );
    println!(
        "{}",
        serde_json::to_string_pretty(
            &json!({"scope":"manual native initialization only; no frame or desktop qualification","native_compositor":false,"initialization_healthy":initialization_healthy,"event_loop_budget_ms":15000,"universal_shutdown_deadline":false,"before_stop":before,"after_stop":after,"prepared_gpus":gpus,"input_events":state.input_events,"gpu_preparations":state.gpu_preparations,"gpu_removals":state.gpu_removals,"session_transitions":state.session_transitions,"vblanks":state.vblanks,"failures":state.failures,"failure_events":state.failure_events,"failures_truncated":state.failure_events>32,"close_failures":close_failures})
        )?
    );
    // Keep the dispatcher (and blocked termination signals) through cleanup.
    drop(event_loop);
    drop(signal_owner);
    if !initialization_healthy {
        return Err("native initialization or cleanup reported failures".into());
    }
    Ok(())
}

#!/usr/bin/env python3
"""Exercise audit denials on owned, harmless syscall fixtures; no seat is opened."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess

SOURCE = r'''
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/syscall.h>
#include <unistd.h>
int main(int argc, char **argv) {
    (void)argc;
    if (strstr(argv[0], "creat"))
        syscall(SYS_creat, "/dev/nvidia-fluxwm-audit-missing", 0600);
    if (strstr(argv[0], "vendor"))
        syscall(SYS_openat, AT_FDCWD, "/dev/nvidia-fluxwm-audit-missing", O_RDONLY);
    if (strstr(argv[0], "console"))
        syscall(SYS_openat, AT_FDCWD, "/dev/console-fluxwm-audit-missing", O_RDONLY);
    if (strstr(argv[0], "ioctl")) {
        int fd = open("/dev/null", O_RDONLY);
        ioctl(fd, 0x4b3a, 0); /* KDSETMODE family, harmless /dev/null fixture */
        close(fd);
    }
    if (strstr(argv[0], "handle"))
        syscall(SYS_open_by_handle_at, -1, NULL, 0);
    if (strstr(argv[0], "compat")) {
        long result;
        __asm__ volatile("int $0x80" : "=a"(result) : "0"(20) : "memory"); /* i386 getpid */
    }
    puts("{\"session_opened\":false,\"gpu_contexts_created\":0,\"native_compositor\":false}");
    return 0;
}
'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--artifacts', type=Path, required=True)
    args = parser.parse_args()
    out = args.artifacts.resolve()
    out.mkdir(parents=True)
    source = out / 'fixture.c'
    source.write_text(SOURCE)
    binary = out / 'normal'
    subprocess.run(['cc', '-Wall', '-Wextra', '-Werror', str(source), '-o', str(binary)], check=True)
    rows = []
    for case, reason in [('normal', None), ('creat', 'native-device-open'),
                         ('vendor', 'native-device-open'), ('console', 'native-device-open'),
                         ('ioctl', 'native-device-ioctl-family'), ('handle', 'file-handle-access'),
                         ('compat', 'unsupported syscall ABI')]:
        executable = out / case
        if case != 'normal':
            os.link(binary, executable)
        command = ['python3', 'tools/check_native_probe.py', '--binary', str(executable),
                   '--artifacts', str(out / (case + '-audit'))]
        completed = subprocess.run(command, capture_output=True, timeout=35)
        (out / (case + '.log')).write_bytes(completed.stdout + completed.stderr)
        result = json.loads((out / (case + '-audit/result.json')).read_text())
        observed = ([item['reason'] for item in result['blocked_calls']] + [result.get('error')])
        ok = (completed.returncode == (1 if reason else 0) and result['child_reaped'] and
              result['binary_unchanged'] and result['harness_unchanged'] and
              (reason in observed if reason else result['ok']))
        rows.append(dict(case=case, expected=reason, observed=observed, ok=ok,
                         command=command, exit_code=completed.returncode))
    (out / 'results.json').write_text(json.dumps(dict(
        source_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),
        binary_sha256=hashlib.sha256(binary.read_bytes()).hexdigest(), cases=rows), indent=2) + '\n')
    print(json.dumps(dict(ok=all(row['ok'] for row in rows), cases=len(rows))))
    return 0 if all(row['ok'] for row in rows) else 1


if __name__ == '__main__':
    raise SystemExit(main())

